// Raio-X da Reforma site. Config comes from config.js (window.RX, generated by src/pay.py / src/raiox.py number).
(function () {
  var c = window.RX || {};
  var all = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };

  // WhatsApp buttons (data-wa = prefilled text), Mercado Pago button (data-pagar), seller, phone, price
  all("[data-wa]").forEach(function (a) {
    if (c.whatsapp) {
      a.href = "https://wa.me/" + c.whatsapp + "?text=" + encodeURIComponent(a.getAttribute("data-wa"));
      a.target = "_blank"; a.rel = "noopener";
    } else {
      a.href = "#preco"; a.title = "WhatsApp em breve";
    }
  });
  all("[data-pagar]").forEach(function (a) {
    if (c.pagar) { a.href = c.pagar; a.target = "_blank"; a.rel = "noopener"; } else { a.style.display = "none"; }
  });
  if (c.vendedor) all("[data-vendedor]").forEach(function (s) { s.textContent = c.vendedor; });
  if (c.whatsapp) {
    var p = c.whatsapp.slice(2), fone = "(" + p.slice(0, 2) + ") " + p.slice(2, -4) + "-" + p.slice(-4);
    all("[data-fone]").forEach(function (s) { s.textContent = fone; });
  }
  if (c.preco) all("[data-preco]").forEach(function (s) { s.textContent = "R$ " + Number(c.preco).toLocaleString("pt-BR"); });

  // Dated copy: a deadline that has passed leaves the page by itself (data-ate = last day shown, data-desde = first day shown)
  var hoje = new Date(), iso = hoje.getFullYear() + "-" + ("0" + (hoje.getMonth() + 1)).slice(-2) + "-" + ("0" + hoje.getDate()).slice(-2);
  all("[data-ate]").forEach(function (e) { if (iso > e.getAttribute("data-ate")) e.hidden = true; });
  all("[data-desde]").forEach(function (e) { if (iso < e.getAttribute("data-desde")) e.hidden = true; });

  // The example: numbers copied from the sample PDF (fictional company), page 2 table "Simples × IBS/CBS por fora".
  var EX = {
    "2027": { v: [-63348, -16869, 24592], pe: 70 },
    "2029": { v: [-70880, -18348, 28513], pe: 70 },
    "2031": { v: [-84892, -20825, 36324], pe: 68 },
    "2033": { v: [-124407, -25185, 63323], pe: 65 }
  };
  var CEN = ["sem nenhum comprador aproveitando crédito", "com os compradores como estão hoje", "com todo comprador com CNPJ aproveitando crédito"];
  var LO = -130000, HI = 70000;
  var pct = function (n) { return ((n - LO) / (HI - LO)) * 100; };
  var brl = function (n) { return (n < 0 ? "−" : "+") + "R$ " + Math.abs(n).toLocaleString("pt-BR"); };
  var valor = document.getElementById("ex-valor"), leitura = document.getElementById("ex-leitura"), pe = document.getElementById("ex-pe");
  function exemplo() {
    var ano = (document.querySelector('input[name="ano"]:checked') || {}).value || "2027";
    var cen = +((document.querySelector('input[name="cen"]:checked') || {}).value || 1);
    var n = EX[ano].v[cen];
    valor.textContent = brl(n);
    valor.classList.toggle("pos", n > 0);
    leitura.textContent = "por ano recolhendo o IBS/CBS por fora, em " + ano + ", " + CEN[cen] + ". " +
      (n < 0 ? "Neste cenário do exemplo, ficar com tudo no DAS tende a favorecer." : "Neste cenário do exemplo, recolher por fora tende a favorecer.");
    pe.textContent = "Ponto de equilíbrio em " + ano + ": só compensa se pelo menos " + EX[ano].pe + "% das vendas forem pra quem aproveita crédito. Hoje são 52%.";
    all("#ex-faixas li").forEach(function (li) {
      var d = EX[li.getAttribute("data-ano")], on = li.getAttribute("data-ano") === ano;
      li.classList.toggle("on", on);
      li.querySelector(".faixa__barra").style.left = pct(d.v[0]) + "%";
      li.querySelector(".faixa__barra").style.width = (pct(d.v[2]) - pct(d.v[0])) + "%";
      li.querySelector(".faixa__zero").style.left = pct(0) + "%";
      li.querySelector(".faixa__marca").style.left = pct(d.v[cen]) + "%";
      li.querySelector("em").textContent = brl(d.v[cen]);
    });
  }
  if (valor) { all('input[name="ano"], input[name="cen"]').forEach(function (i) { i.addEventListener("change", exemplo); }); exemplo(); }

  // How it works: one range input drives the clause and its fragment (without script all four stages are listed)
  var etapas = all("#etapas > li"), trilho = document.getElementById("trilho"), range = document.getElementById("etapa");
  if (range && etapas.length) {
    trilho.hidden = false;
    var nomes = all("li", trilho);
    var ir = function () {
      var i = +range.value;
      etapas.forEach(function (li, k) { li.classList.toggle("on", k === i); });
      nomes.forEach(function (li, k) { li.classList.toggle("on", k === i); });
      range.style.setProperty("--p", (i / 3) * 100 + "%");
      range.setAttribute("aria-valuetext", etapas[i].querySelector("h3").textContent);
    };
    range.addEventListener("input", ir); ir();
  }

  var calm = window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;

  // Hero: the pages of the sample change slowly, like a film being swapped on the light box
  var folhas = all(".hero__obj img");
  if (folhas.length > 1 && !calm) {
    var k = 0;
    setInterval(function () {
      if (document.hidden) return;
      folhas[k].classList.remove("on"); k = (k + 1) % folhas.length; folhas[k].classList.add("on");
    }, 6000);
  }

  // Entrance of the parts of each section
  var partes = all("[data-r]");
  if (calm || !("IntersectionObserver" in window)) { partes.forEach(function (e) { e.classList.add("in"); }); return; }
  var io = new IntersectionObserver(function (es) {
    var n = 0;
    es.forEach(function (e) {
      if (!e.isIntersecting) return;
      e.target.style.setProperty("--d", (n++ * 80) + "ms");
      e.target.classList.add("in"); io.unobserve(e.target);
    });
  }, { rootMargin: "0px 0px -8% 0px" });
  partes.forEach(function (e) { io.observe(e); });
})();
